1397	  display: flex;
1398	  align-items: center;
1399	  gap: 9px;
1400	  padding: 10px 14px;
1401	  background: var(--surf-2);
1402	  border: 1px solid var(--line-bright);
1403	  border-left-width: 3px;
1404	  border-radius: var(--r);
1405	  font-family: var(--f-mono);
