/** The study-detail cockpit: status strip, the etched four-pane grid (brief,
 *  data contract, experiment cards, run table, evidence ledger), and the dock. */
import { useMemo } from 'react'
import { useStudy, useStudyActions } from '../api/hooks'
import { deriveBannedColumns, methodologicalFlag, primaryMetricKey } from '../lib/derive'
import { mergeStudyDetail, useOverlay } from '../state/overlay'
import { ErrorState } from './primitives'
import { StatusStrip } from './panes/StatusStrip'
import { BriefPane } from './panes/BriefPane'
import { DataContractPane } from './panes/DataContractPane'
import { ExperimentCards } from './panes/ExperimentCards'
import { RunTable } from './panes/RunTable'
import { EvidenceLedger } from './panes/EvidenceLedger'
import { Dock } from './panes/Dock'

export function StudyDetail({ studyId }: { studyId: string }) {
  const query = useStudy(studyId)
  const { overlay } = useOverlay(studyId)

  const detail = useMemo(
    () => (query.data ? mergeStudyDetail(query.data, overlay) : undefined),
    [query.data, overlay],
  )

  const study = detail?.study
  const actions = useStudyActions(studyId, { budgetSeconds: study?.budget?.budget_seconds })

  const banned = useMemo(() => {
    if (!detail) return new Set<string>()
    const set = deriveBannedColumns(detail)
    overlay.banned.forEach((c) => set.add(c))
    return set
  }, [detail, overlay.banned])

  const flag = detail ? methodologicalFlag(detail) : undefined
  const metricKey = study ? primaryMetricKey(study) : undefined
  const loading = query.isLoading
  const runs = detail?.runs ?? []
  const computing = runs.some((r) => r.status === 'running')

  return (
    <div className="app">
      {computing && <div className="live-hairline" aria-hidden="true" />}
      <StatusStrip study={study} runs={runs} flag={flag} />

      {query.isError ? (
        <div style={{ display: 'grid', placeItems: 'center', minHeight: 0 }}>
          <ErrorState error={query.error} onRetry={() => query.refetch()} />
        </div>
      ) : (
        <div className="cockpit">
          <BriefPane
            study={study}
            detail={detail}
            banned={banned}
            report={overlay.report}
            grade={overlay.grade}
            loading={loading}
          />
          <DataContractPane
            dataset={detail?.dataset_version}
            banned={banned}
            actions={actions}
            loading={loading}
          />
          <ExperimentCards
            hypotheses={detail?.hypotheses}
            runs={detail?.runs}
            critiques={detail?.critiques}
            banned={banned}
            reruns={overlay.reruns}
            actions={actions}
            metricKey={metricKey}
            loading={loading}
          />
          <RunTable
            runs={detail?.runs}
            hypotheses={detail?.hypotheses}
            critiques={detail?.critiques}
            metricKey={metricKey}
            loading={loading}
          />
          <EvidenceLedger detail={detail} metricKey={metricKey} loading={loading} />
        </div>
      )}

      <Dock
        study={study}
        recommendation={detail?.recommendation}
        flag={flag}
        actions={actions}
        report={overlay.report}
      />
    </div>
  )
}

/** Persistent top readout: brand, study id, objective, target/metric chips, a
 *  budget gauge, and the global status lamp. The lamp flips red on a flag. */
import type { Critique, Run, Study } from '../../api/types'
import { CRITIQUE_LABEL, isActiveStatus } from '../../lib/derive'

type LampTone = 'flag' | 'running' | 'queued' | 'idle'

function lamp(flag: Critique | undefined, runs: Run[]): { tone: LampTone; glyph: string; label: string } {
  if (flag) return { tone: 'flag', glyph: '✕', label: `FLAG · ${CRITIQUE_LABEL[flag.kind]}` }
  if (runs.some((r) => r.status === 'running')) return { tone: 'running', glyph: '◉', label: 'RUNNING' }
  if (runs.some((r) => r.status === 'queued')) return { tone: 'queued', glyph: '◌', label: 'QUEUED' }
  return { tone: 'idle', glyph: '●', label: 'IDLE' }
}

export function StatusStrip({
  study,
  runs,
  flag,
}: {
  study?: Study
  runs: Run[]
  flag?: Critique
}) {
  const l = lamp(flag, runs)
  const maxTrials = study?.budget?.max_trials
  const budgetSeconds = study?.budget?.budget_seconds
  const trials = runs.length
  const fillPct = maxTrials ? Math.min(100, (trials / maxTrials) * 100) : 0
  const active = runs.some((r) => isActiveStatus(r.status))

  return (
    <div className="strip">
      <a className="strip__brand" href="#/" title="All studies">
        LABMATE <b>▸</b> MISSION&nbsp;CONTROL
      </a>
      {study && <span className="strip__id">{study.id}</span>}
      <span className="strip__obj">{study?.brief ?? 'No study selected'}</span>

      {study && (
        <span className="strip__chips">
          {study.target && <span className="chip chip--muted">target {study.target}</span>}
          {study.metric && <span className="chip chip--cyan">{study.metric}</span>}
        </span>
      )}

      <span className="strip__gauge" title="Trials run against budget">
        <span className="gauge__row">
          <span>trials</span>
          <span className="gauge__track">
            <span className="gauge__fill" style={{ width: `${fillPct}%` }} />
          </span>
          <span className="tnum">
            {trials}/{maxTrials ?? '—'}
          </span>
        </span>
        <span className="gauge__row">
          <span>budget</span>
          <span className="gauge__track">
            <span
              className="gauge__fill"
              style={{ width: active ? '100%' : '0%', background: 'var(--amber-dim)' }}
            />
          </span>
          <span className="tnum">{budgetSeconds ?? '—'}s</span>
        </span>
      </span>

      <span className={`lamp lamp--${l.tone}`}>
        <span className="lamp__dot" aria-hidden="true">
          {l.glyph}
        </span>
        {l.label}
      </span>
    </div>
  )
}

/** Small shared building blocks: the panel frame, loading/empty/error states,
 *  and the settle-on-lock metric readout. */
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { formatMetricValue, guardrailLabel } from '../lib/derive'

/** Render parsed_constraints as mono chips — the NL→constraint translation made
 *  visible (shared by the evidence ledger and the feedback box). */
export function ParsedChips({ parsed }: { parsed?: Record<string, unknown> }) {
  if (!parsed) return null
  const chips: string[] = []
  for (const [key, value] of Object.entries(parsed)) {
    if (value == null) continue
    if (key === 'primary_metric') chips.push(`primary · ${String(value)}`)
    else if (key === 'guardrail' || key === 'guardrails') {
      const list = Array.isArray(value) ? value : [value]
      list.forEach((v) => chips.push(guardrailLabel(String(v))))
    } else chips.push(`${key.replace(/_/g, ' ')} · ${String(value)}`)
  }
  if (chips.length === 0) return null
  return (
    <span className="feedback__chips">
      {chips.map((c) => (
        <span className="chip chip--cyan" key={c}>
          {c}
        </span>
      ))}
    </span>
  )
}

export function Panel({
  num,
  title,
  areaClass,
  acquiring = false,
  meta,
  flush = false,
  crosshair = false,
  children,
}: {
  num: string
  title: string
  areaClass?: string
  acquiring?: boolean
  meta?: ReactNode
  flush?: boolean
  crosshair?: boolean
  children: ReactNode
}) {
  return (
    <section className={`panel ${areaClass ?? ''}`}>
      <header className={`panel__head ${acquiring ? 'panel__head--acquiring' : ''}`}>
        <span className="panel__num">§{num}</span>
        <span className="panel__title" role="heading" aria-level={2}>
          {acquiring ? 'ACQUIRING…' : title}
        </span>
        {meta != null && <span className="panel__meta">{meta}</span>}
      </header>
      <div
        className={`panel__body ${flush ? 'panel__body--flush' : ''} ${crosshair ? 'crosshair' : ''}`}
      >
        {children}
      </div>
    </section>
  )
}

export function EmptyState({ label, children }: { label: string; children?: ReactNode }) {
  return (
    <div className="empty">
      {children}
      <span className="empty__label" role="heading" aria-level={3}>
        {label}
      </span>
    </div>
  )
}

export function ErrorState({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  const message = error instanceof Error ? error.message : String(error)
  return (
    <div className="panel-error" role="alert">
      <span className="panel-error__title" role="heading" aria-level={3}>
        ⚠ Signal lost
      </span>
      <span className="panel-error__detail">{message}</span>
      {onRetry && (
        <button type="button" className="btn" onClick={onRetry}>
          Retry
        </button>
      )}
    </div>
  )
}

export function SkeletonRows({ rows = 4 }: { rows?: number }) {
  return (
    <div className="skel-stack">
      {Array.from({ length: rows }, (_, i) => (
        <div className="skel-row" key={i}>
          <span className="skel" style={{ width: '38%' }} />
          <span className="skel" style={{ width: '24%' }} />
          <span className="skel" style={{ flex: 1 }} />
        </div>
      ))}
    </div>
  )
}

export function Flatline() {
  return (
    <svg className="flatline" viewBox="0 0 200 40" fill="none" aria-hidden="true">
      <path
        d="M0 20 H70 l6 -13 l9 26 l7 -13 H200"
        stroke="var(--cyan-dim)"
        strokeWidth="1.5"
      />
    </svg>
  )
}

function scrambleDigits(): string {
  return `0.${Math.floor(Math.random() * 900 + 100)}`
}

/** Hero metric: scrambles digits while a run is live, then locks with a green flash. */
export function MetricReadout({
  value,
  running = false,
  format = formatMetricValue,
}: {
  value?: number
  running?: boolean
  format?: (n: number) => string
}) {
  const [display, setDisplay] = useState(() => (value != null ? format(value) : '–.–––'))
  const [locking, setLocking] = useState(false)
  const prev = useRef<number | undefined>(value)

  useEffect(() => {
    if (running) {
      setLocking(false)
      const id = window.setInterval(() => setDisplay(scrambleDigits()), 90)
      return () => window.clearInterval(id)
    }
    if (value != null) {
      setDisplay(format(value))
      if (prev.current !== value && Number.isFinite(value)) {
        prev.current = value
        setLocking(true)
        const t = window.setTimeout(() => setLocking(false), 700)
        return () => window.clearTimeout(t)
      }
      return undefined
    }
    setDisplay('–.–––')
    return undefined
  }, [running, value, format])

  return <span className={`metric-hero ${locking ? 'is-locking' : ''}`}>{display}</span>
}

/** §01 BRIEF + RUBRIC — objective, metric + rationale, budget, derived guardrails,
 *  and a definition-of-done checklist (authoritative grade if present, else a
 *  live readiness readout derived from the ledger). */
import type { GradeResult, Report, Study, StudyDetail } from '../../api/types'
import {
  deriveGuardrails,
  guardrailLabel,
  methodologicalFlag,
} from '../../lib/derive'
import { EmptyState, Panel, SkeletonRows } from '../primitives'

type Check = { id: string; label: string; pass: boolean; keystone?: boolean }

function readiness(detail: StudyDetail, banned: Set<string>, report?: Report): Check[] {
  const runs = detail.runs ?? []
  const critiques = detail.critiques ?? []
  const decisions = detail.decisions ?? []
  const artifacts = detail.artifacts ?? []
  const baseline = runs.some(
    (r) => (r.tags ?? []).some((t) => /baseline/i.test(t)) || /baseline/i.test(r.hypothesis_id),
  )
  return [
    { id: 'contract', label: 'Data contract written', pass: Boolean(detail.dataset_version) },
    { id: 'baseline', label: 'Baseline model ran', pass: baseline },
    { id: 'five', label: '≥ 5 experiments ran', pass: runs.length >= 5 },
    {
      id: 'leakage',
      label: 'Leakage review',
      pass: critiques.some((c) => c.kind === 'leakage') || banned.size > 0,
    },
    {
      id: 'best',
      label: 'Best vs baseline',
      pass: decisions.some((d) => d.action === 'promote') || Boolean(report?.compares_best_to_baseline),
    },
    {
      id: 'report',
      label: 'Report / model card',
      pass: artifacts.some((a) => a.kind === 'report') || Boolean(report),
    },
    { id: 'feedback', label: 'Human feedback recorded', pass: (detail.feedback ?? []).length > 0 },
    { id: 'caught_an_issue', label: 'Caught an issue', pass: Boolean(methodologicalFlag(detail)), keystone: true },
  ]
}

function ReadinessRow({ check }: { check: Check }) {
  const cls = check.pass ? 'check--pass' : 'check--pending'
  return (
    <div className={`check ${cls} ${check.keystone ? 'check--keystone' : ''}`}>
      <span className="check__glyph" aria-hidden="true">
        {check.pass ? '●' : '○'}
      </span>
      <span>{check.label}</span>
      {!check.pass && <span className="check__opt">awaiting</span>}
    </div>
  )
}

function GradeRow({
  check,
}: {
  check: GradeResult['checks'][number]
}) {
  const keystone = check.id === 'caught_an_issue'
  const cls = check.passed ? 'check--pass' : check.required ? 'check--fail' : 'check--pending'
  const glyph = check.passed ? '●' : check.required ? '✕' : '○'
  return (
    <div className={`check ${cls} ${keystone ? 'check--keystone' : ''}`} title={check.detail ?? ''}>
      <span className="check__glyph" aria-hidden="true">
        {glyph}
      </span>
      <span>{check.id.replace(/_/g, ' ')}</span>
      <span className="check__opt">{check.required ? 'required' : 'optional'}</span>
    </div>
  )
}

export function BriefPane({
  study,
  detail,
  banned,
  report,
  grade,
  loading = false,
}: {
  study?: Study
  detail?: StudyDetail
  banned: Set<string>
  report?: Report
  grade?: GradeResult
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!study || !detail) return <EmptyState label="No study loaded" />

    const guards = deriveGuardrails(detail)
    const checks = readiness(detail, banned, report)

    return (
      <>
        <p className="brief__objective">{study.brief}</p>

        <div className="kv">
          <span className="kv__k">Target</span>
          <span className="kv__v">{study.target}</span>
          <span className="kv__k">Task</span>
          <span className="kv__v">{study.task_type ?? '—'}</span>
          <span className="kv__k">Metric</span>
          <span className="kv__v">{study.metric}</span>
          {study.metric_rationale && (
            <>
              <span className="kv__k">Why</span>
              <span className="kv__v kv__v--prose">{study.metric_rationale}</span>
            </>
          )}
          <span className="kv__k">Max trials</span>
          <span className="kv__v">{study.budget?.max_trials ?? '—'}</span>
          <span className="kv__k">Budget</span>
          <span className="kv__v">{study.budget?.budget_seconds ?? '—'}s</span>
          <span className="kv__k">Status</span>
          <span className="kv__v">
            <span
              className={`chip ${
                study.status === 'done'
                  ? 'chip--green'
                  : study.status === 'stopped'
                    ? 'chip--danger'
                    : 'chip--cyan'
              }`}
            >
              {study.status}
            </span>
          </span>
        </div>

        <div className="subhead">Guardrails</div>
        <div className="chip-row">
          {guards.primaryMetric && (
            <span className="chip chip--cyan">primary · {guards.primaryMetric}</span>
          )}
          {guards.guardrails.map((g) => (
            <span className="chip chip--amber" key={g}>
              {guardrailLabel(g)}
            </span>
          ))}
          {banned.size > 0 && <span className="chip chip--danger">{banned.size} banned cols</span>}
          {!guards.primaryMetric && guards.guardrails.length === 0 && banned.size === 0 && (
            <span className="parse-hint">none recorded yet — add via the feedback box</span>
          )}
        </div>

        <div className="subhead">{grade ? `Definition of done · ${grade.verdict}` : 'Readiness'}</div>
        <div className="checklist">
          {grade
            ? grade.checks.map((c) => <GradeRow check={c} key={c.id} />)
            : checks.map((c) => <ReadinessRow check={c} key={c.id} />)}
        </div>
      </>
    )
  }

  return (
    <Panel num="01" title="BRIEF + RUBRIC" areaClass="area-brief" acquiring={loading}>
      {body()}
    </Panel>
  )
}

