1	/** §06 CURRENT RECOMMENDATION + the natural-language FEEDBACK BOX (sticky dock). */
2	import { useState } from 'react'
3	import type { Critique, Report, Study } from '../../api/types'
4	import type { StudyActions } from '../../api/hooks'
5	import { CRITIQUE_LABEL, parseConstraints, shortId } from '../../lib/derive'
6	import { ParsedChips } from '../primitives'
7	
8	function splitRecommendation(rec: string | undefined, flag: Critique | undefined): {
9	  verb: string
10	  detail: string
11	} {
12	  const text = (rec ?? '').trim()
13	  if (text) {
14	    const m = text.match(/^(\S+)\s*(.*)$/)
15	    return { verb: (m?.[1] ?? text).toUpperCase(), detail: m?.[2] ?? '' }
16	  }
17	  if (flag) return { verb: 'REVIEW', detail: flag.finding }
18	  return { verb: 'STANDING BY', detail: '' }
19	}
20	
21	function RecommendationDock({
22	  study,
23	  recommendation,
24	  flag,
25	  actions,
26	  report,
27	}: {
28	  study?: Study
29	  recommendation?: string
30	  flag?: Critique
31	  actions: StudyActions
32	  report?: Report
33	}) {
34	  const { verb, detail } = splitRecommendation(recommendation, flag)
35	  const disabled = !study || actions.generateReport.isPending
36	
37	  return (
38	    <div className={`rec ${flag ? 'is-alert' : ''}`}>
39	      <div className="rec__verbwrap">
40	        <div className="rec__kicker">
41	          {flag ? `⚠ Methodological flag · ${CRITIQUE_LABEL[flag.kind]}` : 'Current recommendation'}
42	        </div>
43	        <div className="rec__verb">
44	          {verb}
45	          <span className="caret" aria-hidden="true">
46	            &nbsp;
47	          </span>
48	        </div>
49	        {detail && <div className="rec__detail">{detail}</div>}
50	      </div>
51	
52	      {report && (
53	        <div className="report-out">
54	          <span className="label">Model card</span>
55	          <a href={report.uri} target="_blank" rel="noreferrer">
56	            {report.uri}
57	          </a>
58	          {report.compares_best_to_baseline && (
59	            <span className="chip chip--green">best vs baseline ✓</span>
60	          )}
61	          {report.reproducible_command && <code>{report.reproducible_command}</code>}
62	          {report.provenance?.seed != null && (
63	            <span className="parse-hint">
64	              seed {report.provenance.seed}
65	              {report.provenance.dataset_hash
66	                ? ` · data ${shortId(report.provenance.dataset_hash, 6)}`
67	                : ''}
68	            </span>
69	          )}
70	        </div>
71	      )}
72	
73	      <div className="rec__actions">
74	        <button
75	          type="button"
76	          className="btn btn--primary"
77	          disabled={disabled}
