/** §06 CURRENT RECOMMENDATION + the natural-language FEEDBACK BOX (sticky dock). */
import { useState } from 'react'
import type { Critique, Report, Study } from '../../api/types'
import type { StudyActions } from '../../api/hooks'
import { CRITIQUE_LABEL, parseConstraints, shortId } from '../../lib/derive'
import { ParsedChips } from '../primitives'

function splitRecommendation(rec: string | undefined, flag: Critique | undefined): {
  verb: string
  detail: string
} {
  const text = (rec ?? '').trim()
  if (text) {
    const m = text.match(/^(\S+)\s*(.*)$/)
    return { verb: (m?.[1] ?? text).toUpperCase(), detail: m?.[2] ?? '' }
  }
  if (flag) return { verb: 'REVIEW', detail: flag.finding }
  return { verb: 'STANDING BY', detail: '' }
}

function RecommendationDock({
  study,
  recommendation,
  flag,
  actions,
  report,
}: {
  study?: Study
  recommendation?: string
  flag?: Critique
  actions: StudyActions
  report?: Report
}) {
  const { verb, detail } = splitRecommendation(recommendation, flag)
  const disabled = !study || actions.generateReport.isPending

  return (
    <div className={`rec ${flag ? 'is-alert' : ''}`}>
      <div className="rec__verbwrap">
        <div className="rec__kicker">
          {flag ? `⚠ Methodological flag · ${CRITIQUE_LABEL[flag.kind]}` : 'Current recommendation'}
        </div>
        <div className="rec__verb">
          {verb}
          <span className="caret" aria-hidden="true">
            &nbsp;
          </span>
        </div>
        {detail && <div className="rec__detail">{detail}</div>}
      </div>

      {report && (
        <div className="report-out">
          <span className="label">Model card</span>
          <a href={report.uri} target="_blank" rel="noreferrer">
            {report.uri}
          </a>
          {report.compares_best_to_baseline && (
            <span className="chip chip--green">best vs baseline ✓</span>
          )}
          {report.reproducible_command && <code>{report.reproducible_command}</code>}
          {report.provenance?.seed != null && (
            <span className="parse-hint">
              seed {report.provenance.seed}
              {report.provenance.dataset_hash
                ? ` · data ${shortId(report.provenance.dataset_hash, 6)}`
                : ''}
            </span>
          )}
        </div>
      )}

      <div className="rec__actions">
        <button
          type="button"
          className="btn btn--primary"
          disabled={disabled}
          onClick={() => actions.generateReport.mutate()}
        >
          {actions.generateReport.isPending ? 'Generating…' : 'Generate report'}
        </button>
        <button
          type="button"
          className="btn btn--ghost"
          disabled={!study || actions.checkDone.isPending}
          onClick={() => actions.checkDone.mutate()}
        >
          {actions.checkDone.isPending ? 'Grading…' : 'Check done'}
        </button>
      </div>
    </div>
  )
}

function FeedbackBox({ study, actions }: { study?: Study; actions: StudyActions }) {
  const [text, setText] = useState('')
  const preview = parseConstraints(text)
  const pending = actions.sendFeedback.isPending

  const submit = () => {
    const trimmed = text.trim()
    if (!trimmed || !study) return
    actions.sendFeedback.mutate(trimmed)
    setText('')
  }

  return (
    <div className="feedback">
      <span className="feedback__title">Record your judgment</span>
      <div className="feedback__field">
        <textarea
          value={text}
          placeholder="Recall matters more than precision, but false positives above 20% are not acceptable."
          aria-label="Record your judgment as natural language"
          aria-describedby="feedback-hint"
          disabled={!study || pending}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault()
              submit()
            }
          }}
        />
        <button
          type="button"
          className="btn btn--primary"
          disabled={!study || pending || text.trim().length === 0}
          onClick={submit}
        >
          {pending ? '···' : 'Send'}
        </button>
      </div>
      {preview && (
        <div className="feedback__preview">
          <span className="parse-hint">parses to →</span>
          <ParsedChips parsed={preview} />
        </div>
      )}
      <span className="parse-hint" id="feedback-hint">
        Enter to send · Shift+Enter for newline
      </span>
    </div>
  )
}

export function Dock({
  study,
  recommendation,
  flag,
  actions,
  report,
}: {
  study?: Study
  recommendation?: string
  flag?: Critique
  actions: StudyActions
  report?: Report
}) {
  return (
    <div className="dock">
      <RecommendationDock
        study={study}
        recommendation={recommendation}
        flag={flag}
        actions={actions}
        report={report}
      />
      <FeedbackBox study={study} actions={actions} />
    </div>
  )
}

/** Cockpit home — the study registry (GET /api/studies) with a status filter. */
import { useState } from 'react'
import { useStudies } from '../api/hooks'
import type { Study } from '../api/types'
import { hrefFor } from '../lib/router'
import { EmptyState, ErrorState, SkeletonRows } from './primitives'

const FILTERS: { key: Study['status'] | 'all'; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'open', label: 'Open' },
  { key: 'done', label: 'Done' },
  { key: 'stopped', label: 'Stopped' },
]

function statusChip(status: Study['status']) {
  const cls = status === 'done' ? 'chip--green' : status === 'stopped' ? 'chip--danger' : 'chip--cyan'
  return <span className={`chip ${cls}`}>{status}</span>
}

export function StudyList() {
  const [filter, setFilter] = useState<Study['status'] | 'all'>('all')
  const query = useStudies(filter === 'all' ? undefined : filter)
  const studies = query.data?.studies ?? []

  return (
    <div className="app" style={{ gridTemplateRows: 'var(--strip-h) 1fr' }}>
      <div className="strip">
        <span className="strip__brand">
          LABMATE <b>▸</b> MISSION&nbsp;CONTROL
        </span>
        <span className="strip__obj">Study registry — the agent&apos;s evidence ledgers</span>
        <span className="lamp lamp--idle">
          <span className="lamp__dot" aria-hidden="true">
            ●
          </span>
          {studies.length} studies
        </span>
      </div>

      <div className="listview">
        <div className="listview__head">
          <div>
            <h1 className="listview__title">Studies</h1>
            <div className="listview__sub">
              hypothesis → experiment → evidence → decision
            </div>
          </div>
          <div className="filterow">
            {FILTERS.map((f) => (
              <button
                key={f.key}
                type="button"
                className={`filterchip ${filter === f.key ? 'is-active' : ''}`}
                onClick={() => setFilter(f.key)}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>

        {query.isLoading ? (
          <SkeletonRows rows={6} />
        ) : query.isError ? (
          <ErrorState error={query.error} onRetry={() => query.refetch()} />
        ) : studies.length === 0 ? (
          <EmptyState label="No studies — create one via the MCP create_study tool" />
        ) : (
          <div className="studygrid">
            {studies.map((s, i) => (
              <a className="studycard" key={s.id || i} href={hrefFor({ name: 'study', id: s.id })}>
                <div className="studycard__top">
                  <span className="studycard__id">{s.id}</span>
                  {statusChip(s.status)}
                </div>
                <p className="studycard__brief">{s.brief}</p>
                <div className="studycard__foot">
                  {s.target && <span className="chip chip--muted">target {s.target}</span>}
                  {s.metric && <span className="chip chip--cyan">{s.metric}</span>}
                  {s.task_type && <span className="chip chip--muted">{s.task_type}</span>}
                </div>
              </a>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

/** §03 EXPERIMENT CARDS — one card per hypothesis with the latest run's metric,
 *  agent rationale, and the Approve / Deny / Rerun segmented control. */
import type { Critique, Hypothesis, Run } from '../../api/types'
import type { StudyActions } from '../../api/hooks'
import {
  CRITIQUE_LABEL,
  critiquesForRun,
  latestRun,
  metricLabel,
  pickPrimaryMetric,
  runsForHypothesis,
} from '../../lib/derive'
import { EmptyState, MetricReadout, Panel, SkeletonRows } from '../primitives'

function statusChip(status: Hypothesis['status']) {
  if (status === 'approved') return <span className="chip chip--cyan">approved</span>
  if (status === 'rejected') return <span className="chip chip--struck">rejected</span>
  return <span className="chip chip--amber">proposed</span>
}

function Card({
  hyp,
  runs,
  critiques,
  banned,
  rerunRequested,
  actions,
  metricKey,
}: {
  hyp: Hypothesis
  runs: Run[]
  critiques: Critique[]
  banned: Set<string>
  rerunRequested: boolean
  actions: StudyActions
  metricKey?: string
}) {
  const run = latestRun(runsForHypothesis(runs, hyp.id))
  const primary = run ? pickPrimaryMetric(run, metricKey) : undefined
  const linked = critiquesForRun(critiques, run?.id)
  const flag = linked.find((c) => c.kind === 'leakage' || c.kind === 'test_set_tuning')
  const running = run?.status === 'running'
  const status = hyp.status ?? 'proposed'

  const approvePending = actions.approve.isPending && actions.approve.variables?.id === hyp.id
  const denyPending = actions.deny.isPending && actions.deny.variables?.id === hyp.id
  const rerunPending = actions.rerun.isPending && actions.rerun.variables?.id === hyp.id

  return (
    <article
      className={`xcard ${status === 'approved' ? 'is-approved' : ''} ${
        status === 'rejected' ? 'is-rejected' : ''
      } ${flag ? 'is-flagged' : ''} ${running ? 'is-busy' : ''}`}
    >
      {flag && (
        <div className="xcard__flag">
          <span aria-hidden="true">⚠</span> {CRITIQUE_LABEL[flag.kind]} — {flag.finding}
        </div>
      )}

      <div className="xcard__top">
        <h3 className="xcard__statement">{hyp.statement}</h3>
        {statusChip(status)}
      </div>

      {hyp.rationale && <p className="xcard__rationale">{hyp.rationale}</p>}

      <div className="xcard__chips">
        {hyp.model_family && <span className="chip chip--cyan">{hyp.model_family}</span>}
        {(hyp.features ?? []).map((f) => (
          <span className={`chip ${banned.has(f) ? 'chip--struck' : 'chip--muted'}`} key={f}>
            {f}
          </span>
        ))}
      </div>

      {hyp.expected_outcome && <p className="xcard__expected">Expected: {hyp.expected_outcome}</p>}

      <div className="xcard__metricwrap">
        {run ? (
          <>
            <MetricReadout value={primary?.value} running={running} />
            <span className="metric-hero__label">
              {primary ? metricLabel(primary.key) : 'no metric'}
              {running && <span className="xcard__elapsed">◉ acquiring…</span>}
            </span>
          </>
        ) : (
          <span className="metric-hero__label">no run yet</span>
        )}
      </div>

      <div className="xcard__foot">
        <div className="segmented" role="group" aria-label="experiment actions">
          <button
            type="button"
            className={`seg ${status === 'approved' ? 'seg--on-approve' : ''}`}
            disabled={status !== 'proposed' || approvePending}
            onClick={() => actions.approve.mutate(hyp)}
          >
            {approvePending ? <span className="seg__spin">···</span> : 'Approve'}
          </button>
          <button
            type="button"
            className={`seg ${status === 'rejected' ? 'seg--on-deny' : ''}`}
            disabled={status !== 'proposed' || denyPending}
            onClick={() => actions.deny.mutate(hyp)}
          >
            {denyPending ? <span className="seg__spin">···</span> : 'Deny'}
          </button>
          <button
            type="button"
            className="seg"
            disabled={rerunPending}
            onClick={() => actions.rerun.mutate(hyp)}
          >
            {rerunPending ? <span className="seg__spin">···</span> : 'Rerun'}
          </button>
        </div>
        {rerunRequested && <span className="chip chip--cyan">rerun requested</span>}
      </div>
    </article>
  )
}

export function ExperimentCards({
  hypotheses = [],
  runs = [],
  critiques = [],
  banned,
  reruns,
  actions,
  metricKey,
  loading = false,
}: {
  hypotheses?: Hypothesis[]
  runs?: Run[]
  critiques?: Critique[]
  banned: Set<string>
  reruns: string[]
  actions: StudyActions
  metricKey?: string
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={4} />
    if (hypotheses.length === 0) {
      return (
        <EmptyState label="No experiments proposed">
          <div className="ghost-card">[ + PROPOSE HYPOTHESIS ]</div>
        </EmptyState>
      )
    }
    return (
      <div className="cards">
        {hypotheses.map((hyp) => (
          <Card
            key={hyp.id}
            hyp={hyp}
            runs={runs}
            critiques={critiques}
            banned={banned}
            rerunRequested={reruns.includes(hyp.id)}
            actions={actions}
            metricKey={metricKey}
          />
        ))}
      </div>
    )
  }

  return (
    <Panel
      num="03"
      title="EXPERIMENT CARDS"
      areaClass="area-cards"
      acquiring={loading}
      meta={hypotheses.length > 0 ? `${hypotheses.length} hypotheses` : undefined}
    >
      {body()}
    </Panel>
  )
}

