1534	    animation-duration: 0.001ms !important;
1535	    animation-iteration-count: 1 !important;
1536	  }
1537	}
1538	
1539	/* ============================================================================
1540	   RESPONSIVE — canonical wide frame ≥1280; below, stack into a scrolling column
1541	   ============================================================================ */
