  if (status === 'rejected') return <span className="chip chip--struck">rejected</span>
  return <span className="chip chip--amber">proposed</span>
}

function Card({
  hyp,
  runs,
  critiques,
  banned,
  rerunRequested,
  actions,
  metricKey,
}: {
  hyp: Hypothesis
  runs: Run[]
  critiques: Critique[]
  banned: Set<string>
  rerunRequested: boolean
  actions: StudyActions
  metricKey?: string
}) {
  const run = latestRun(runsForHypothesis(runs, hyp.id))
  const primary = run ? pickPrimaryMetric(run, metricKey) : undefined
  const linked = critiquesForRun(critiques, run?.id)
  const flag = linked.find((c) => c.kind === 'leakage' || c.kind === 'test_set_tuning')
  const running = run?.status === 'running'
  const status = hyp.status ?? 'proposed'

  const approvePending = actions.approve.isPending && actions.approve.variables?.id === hyp.id
  const denyPending = actions.deny.isPending && actions.deny.variables?.id === hyp.id
  const rerunPending = actions.rerun.isPending && actions.rerun.variables?.id === hyp.id

  return (
    <article
      className={`xcard ${status === 'approved' ? 'is-approved' : ''} ${
        status === 'rejected' ? 'is-rejected' : ''
      } ${flag ? 'is-flagged' : ''} ${running ? 'is-busy' : ''}`}
    >
      {flag && (
        <div className="xcard__flag">
          <span aria-hidden="true">⚠</span> {CRITIQUE_LABEL[flag.kind]} — {flag.finding}
        </div>
      )}

      <div className="xcard__top">
        <h3 className="xcard__statement">{hyp.statement}</h3>
        {statusChip(status)}
      </div>

      {hyp.rationale && <p className="xcard__rationale">{hyp.rationale}</p>}

      <div className="xcard__chips">
        {hyp.model_family && <span className="chip chip--cyan">{hyp.model_family}</span>}
        {(hyp.features ?? []).map((f) => (
          <span className={`chip ${banned.has(f) ? 'chip--struck' : 'chip--muted'}`} key={f}>
            {f}
          </span>
        ))}
      </div>

      {hyp.expected_outcome && <p className="xcard__expected">Expected: {hyp.expected_outcome}</p>}

      <div className="xcard__metricwrap">
        {run ? (
          <>
            <MetricReadout value={primary?.value} running={running} />
            <span className="metric-hero__label">
              {primary ? metricLabel(primary.key) : 'no metric'}
              {running && <span className="xcard__elapsed">◉ acquiring…</span>}
            </span>
          </>
        ) : (
          <span className="metric-hero__label">no run yet</span>
        )}
      </div>

      <div className="xcard__foot">
        <div className="segmented" role="group" aria-label="experiment actions">
          <button
            type="button"
            className={`seg ${status === 'approved' ? 'seg--on-approve' : ''}`}
            disabled={status !== 'proposed' || approvePending}
            onClick={() => actions.approve.mutate(hyp)}
          >
            {approvePending ? <span className="seg__spin">···</span> : 'Approve'}
          </button>
          <button
            type="button"
            className={`seg ${status === 'rejected' ? 'seg--on-deny' : ''}`}
            disabled={status !== 'proposed' || denyPending}
            onClick={() => actions.deny.mutate(hyp)}
          >
            {denyPending ? <span className="seg__spin">···</span> : 'Deny'}
          </button>
          <button
            type="button"
            className="seg"
            disabled={rerunPending}
            onClick={() => actions.rerun.mutate(hyp)}
          >
            {rerunPending ? <span className="seg__spin">···</span> : 'Rerun'}
          </button>
        </div>
        {rerunRequested && <span className="chip chip--cyan">rerun requested</span>}
      </div>
    </article>
  )
}

export function ExperimentCards({
  hypotheses = [],
  runs = [],
  critiques = [],
  banned,
  reruns,
  actions,
  metricKey,
  loading = false,
}: {
  hypotheses?: Hypothesis[]
  runs?: Run[]
  critiques?: Critique[]
  banned: Set<string>
  reruns: string[]
  actions: StudyActions
  metricKey?: string
  loading?: boolean
}) {
  const body = () => {
    if (loading) return <SkeletonRows rows={4} />
    if (hypotheses.length === 0) {
      return (
        <EmptyState label="No experiments proposed">
          <div className="ghost-card">Propose a hypothesis to begin</div>
        </EmptyState>
      )
    }
    return (
      <div className="cards">
        {hypotheses.map((hyp) => (
          <Card
            key={hyp.id}
            hyp={hyp}
            runs={runs}
            critiques={critiques}
            banned={banned}
            rerunRequested={reruns.includes(hyp.id)}
            actions={actions}
            metricKey={metricKey}
          />
        ))}
      </div>
    )
  }

  return (
    <Panel
      title="EXPERIMENT CARDS"
      areaClass="area-cards"
      acquiring={loading}
      meta={hypotheses.length > 0 ? `${hypotheses.length} hypotheses` : undefined}
    >
      {body()}
    </Panel>
  )
}

/** §04 EVIDENCE LEDGER — the product centerpiece. One feed merging runs,
 *  critiques, decisions, and feedback, with an alert pin on a caught issue. */
import type { ReactNode } from 'react'
import type { Decision, DecisionAction, StudyDetail } from '../../api/types'
import {
  buildLedger,
  CRITIQUE_COLOR,
  CRITIQUE_LABEL,
  formatMetricValue,
  type LedgerEntry,
  methodologicalFlag,
  metricLabel,
  pickPrimaryMetric,
  runStatusMeta,
  shortId,
} from '../../lib/derive'
import { EmptyState, Flatline, ParsedChips, SkeletonRows } from '../primitives'

const DECISION_GLYPH: Record<DecisionAction, string> = {
  promote: '↑',
  reject: '✕',
  rerun: '↻',
  branch: '⎇',
  stop: '■',
}
const DECISION_COLOR: Record<DecisionAction, string> = {
  promote: 'var(--st-completed)',
  reject: 'var(--st-failed)',
  rerun: 'var(--cyan)',
  branch: 'var(--crit-calibration)',
  stop: 'var(--amber)',
}

function decisionTarget(d: Decision): string {
  if (d.promoted_run_id) return ` ${shortId(d.promoted_run_id, 6)}`
  if (d.rejected_run_id) return ` ${shortId(d.rejected_run_id, 6)}`
  return ''
}

function Entry({ entry, metricKey }: { entry: LedgerEntry; metricKey?: string }) {
  if (entry.kind === 'run') {
    const run = entry.data
    const meta = runStatusMeta(run.status)
    const primary = pickPrimaryMetric(run, metricKey)
    return (
      <Node color={meta.cssVar} glyph="◆" type="RUN">
        <b>Run {shortId(run.id, 6)}</b> — {meta.label.toLowerCase()}
        {primary && (
          <>
            {' · '}
            {metricLabel(primary.key)} {formatMetricValue(primary.value)}
          </>
        )}
        {run.rationale && <div className="parse-hint">{run.rationale}</div>}
      </Node>
    )
  }
  if (entry.kind === 'critique') {
    const c = entry.data
    return (
      <Node color={CRITIQUE_COLOR[c.kind]} glyph="!" type={CRITIQUE_LABEL[c.kind]}>
        <b>{c.finding}</b>
        {c.recommendation && <div className="parse-hint">→ {c.recommendation}</div>}
        {c.led_to_decision && <span className="chip chip--muted">{c.led_to_decision}</span>}
      </Node>
    )
  }
  if (entry.kind === 'decision') {
    const d = entry.data
    return (
      <Node color={DECISION_COLOR[d.action]} glyph={DECISION_GLYPH[d.action]} type="DECISION">
        <b>
          {d.action}
          {decisionTarget(d)}
        </b>
        {d.reason && <> — {d.reason}</>}
      </Node>
    )
  }
  // feedback
  const f = entry.data
  const parsed = f.parsed_constraints as Record<string, unknown> | undefined
  return (
    <Node color="var(--amber)" glyph="✎" type={f.type}>
      {f.content}
      {parsed && <ParsedChips parsed={parsed} />}
    </Node>
  )
}

function Node({
  color,
  glyph,
  type,
  children,
}: {
  color: string
  glyph: string
  type: string
  children: ReactNode
}) {
  return (
    <div className="tl-entry tl-entry--enter">
      <span className="tl-entry__node" style={{ borderColor: color, color }} aria-hidden="true">
        {glyph}
      </span>
      <div className="tl-entry__head">
        <span className="tl-entry__type" style={{ color }}>
          {type}
        </span>
      </div>
      <div className="tl-entry__body">{children}</div>
    </div>
  )
}

export function EvidenceLedger({
  detail,
  metricKey,
  loading = false,
}: {
  detail?: StudyDetail
  metricKey?: string
  loading?: boolean
}) {
  const flag = detail ? methodologicalFlag(detail) : undefined
  const entries = detail ? buildLedger(detail) : []

  const inner = () => {
    if (loading) return <SkeletonRows rows={6} />
    if (!detail || entries.length === 0) {
      return (
        <EmptyState label="Ledger awaiting first signal">
          <Flatline />
        </EmptyState>
      )
    }
    return (
      <>
        {flag && (
          <div className="alert-pin" role="alert" aria-live="polite">
            <span className="alert-pin__glyph" aria-hidden="true">
              ⚠
            </span>
            <div>
              <div className="alert-pin__title">Methodological flag · {CRITIQUE_LABEL[flag.kind]}</div>
              <div className="alert-pin__body">
                {flag.finding}
                {flag.recommendation && ` — ${flag.recommendation}`}
              </div>
            </div>
          </div>
        )}
        <div className="timeline">
          {entries.map((entry) => (
            <Entry key={`${entry.kind}-${entry.id}`} entry={entry} metricKey={metricKey} />
          ))}
        </div>
      </>
    )
  }

  return (
    <section className="panel area-ledger">
      <header className={`panel__head ${loading ? 'panel__head--acquiring' : ''}`}>
        <span className="panel__num">§04</span>
        <span className="panel__title" role="heading" aria-level={2}>
          {loading ? 'ACQUIRING…' : 'EVIDENCE LEDGER'}
        </span>
        {entries.length > 0 && <span className="panel__meta">{entries.length} events</span>}
      </header>
      <div className="ledger crosshair">{inner()}</div>
    </section>
  )
}

