      manifest.hypothesis_id,
      manifest.model?.family ?? null,
      JSON.stringify(manifest.features || []),
      JSON.stringify(manifest.search || {}),
      JSON.stringify(manifest),
      manifest.split?.seed ?? null,
      manifest.applied_feedback_id ?? null,
      created,
    )
    .run();

