  modalRunnerUrl: () => read("MODAL_RUNNER_URL", { required: true }),

  // This service.
  port: Number(read("AGENT_RUNTIME_PORT", { fallback: "8990" })),

  // Budgets / safety ceilings (defense in depth alongside per-study budget).
  maxToolCallsPerSession: Number(
    read("LABMATE_MAX_TOOL_CALLS", { fallback: "60" }),
  ),
  maxSessionSeconds: Number(read("LABMATE_MAX_SESSION_SECONDS", { fallback: "1800" })),
};

/** Validate everything the runtime needs to actually run (not just bootstrap). */
export function assertRuntimeConfig() {
  config.anthropicApiKey();
  config.agentId();
  config.environmentId();
  config.internalToken();
  config.modalRunnerUrl();
}
===== server.mjs =====
/**
 * Agent runtime HTTP/SSE server.
 *
 *   POST /agent/start            { study_id }      → start a session + loop
 *   GET  /agent/:studyId/stream  (SSE)             → live agent events for the cockpit
 *   POST /agent/:studyId/message { text }          → inject a human "suggest changes" msg
 *   GET  /healthz
 *
 * Uses only Node built-ins (node:http) to avoid a framework dependency. The
 * control plane (apps/web) can proxy /agent/:id/stream through to the cockpit, or
 * the cockpit can hit this directly in local dev.
 *
 * DEPLOYMENT NOTE: for the hackathon you can wrap this as a Modal app — a web
 * endpoint for the POST routes plus a long-running function that holds the event
 * stream — so there's no separate host to manage. The loop code is unchanged;
 * only the process entrypoint differs.
 */
import http from "node:http";
import { config, assertRuntimeConfig } from "./config.mjs";
import * as sdk from "./anthropic.mjs";
import { makeControlPlaneClient } from "./controlplane.mjs";
import { makeDispatcher } from "./dispatch.mjs";
import { runStudyLoop } from "./loop.mjs";

// In-memory registry of live studies → SSE subscribers and last events.
const studies = new Map(); // study_id → { subscribers:Set<res>, buffer:[], sessionId, inject }

function emitter(studyId) {
  return (evt) => {
    const entry = studies.get(studyId);
    if (!entry) return;
    entry.buffer.push(evt);
    if (entry.buffer.length > 500) entry.buffer.shift();
    const line = `data: ${JSON.stringify(evt)}\n\n`;
    for (const res of entry.subscribers) res.write(line);
  };
}

/** Adapter the loop uses; real SDK here, swapped for a stub in tests. */
function realAgentAdapter() {
  return {
    createSession: sdk.createSession,
    sendUserMessage: sdk.sendUserMessage,
    sendToolResult: sdk.sendToolResult,
    streamEvents: sdk.streamEvents,
    // getOutcome: sdk.getOutcome, // wire when the Outcomes preview is enabled
  };
}

async function startStudy(studyId) {
  if (studies.has(studyId)) return studies.get(studyId);
  const entry = { subscribers: new Set(), buffer: [], sessionId: null, injectQueue: [] };
  studies.set(studyId, entry);

  const controlPlane = makeControlPlaneClient();
  const modal = { url: config.modalRunnerUrl() };
  const dispatcher = makeDispatcher({
    controlPlane,
    modal,
    onApprovalNeeded: async (input, res) => emitter(studyId)({ kind: "approval.needed", input, res }),
  });

  const emit = emitter(studyId);

  // Fire-and-forget the loop; it runs until done or the session ends.
  runStudyLoop({
    studyId,
    agent: realAgentAdapter(),
    dispatcher,
    controlPlane,
    emit,
    opts: {
      agentId: config.agentId(),
      environmentId: config.environmentId(),
      maxToolCalls: config.maxToolCallsPerSession,
      outcomesEnabled: config.outcomesEnabled,
    },
  })
    .then((r) => {
      entry.sessionId = r.sessionId;
      emit({ kind: "loop.finished", study_id: studyId, ...r });
    })
    .catch((err) => emit({ kind: "loop.error", study_id: studyId, error: String(err?.message ?? err) }));

  return entry;
}

function send(res, status, obj) {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(obj));
}

async function readBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  if (!chunks.length) return {};
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8"));
  } catch {
    return {};
  }
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://localhost");
  const parts = url.pathname.split("/").filter(Boolean); // ["agent", ":id", "stream"]

  if (req.method === "GET" && url.pathname === "/healthz") return send(res, 200, { ok: true });

  if (req.method === "POST" && url.pathname === "/agent/start") {
    const body = await readBody(req);
    if (!body.study_id) return send(res, 400, { error: "study_id required" });
    try {
      assertRuntimeConfig();
    } catch (e) {
      return send(res, 503, { error: "config", detail: String(e.message) });
    }
    await startStudy(body.study_id);
    return send(res, 202, { status: "started", study_id: body.study_id });
  }

  if (req.method === "GET" && parts[0] === "agent" && parts[2] === "stream") {
    const studyId = decodeURIComponent(parts[1]);
    const entry = studies.get(studyId) ?? (await startStudy(studyId));
    res.writeHead(200, {
      "content-type": "text/event-stream",
      "cache-control": "no-cache",
      connection: "keep-alive",
    });
    // Replay buffered events so a late subscriber catches up.
    for (const evt of entry.buffer) res.write(`data: ${JSON.stringify(evt)}\n\n`);
    entry.subscribers.add(res);
    req.on("close", () => entry.subscribers.delete(res));
    return;
  }

  if (req.method === "POST" && parts[0] === "agent" && parts[2] === "message") {
    const studyId = decodeURIComponent(parts[1]);
    const body = await readBody(req);
    const entry = studies.get(studyId);
    if (!entry?.sessionId) return send(res, 409, { error: "session_not_ready" });
    if (!body.text) return send(res, 400, { error: "text required" });
    await sdk.sendUserMessage(entry.sessionId, `[human guidance] ${body.text}`);
    emitter(studyId)({ kind: "human.guidance", study_id: studyId, text: body.text });
    return send(res, 202, { status: "queued" });
  }

  return send(res, 404, { error: "not_found" });
});

server.listen(config.port, () => {
  console.info(`Labmate agent runtime listening on :${config.port}`);
});
===== loop.mjs =====
/**
 * The session loop — the heart of the runtime.
 *
 * Lifecycle for one study:
 *   1. create a session (agent + environment)
 *   2. send the brief + data contract + rubric as a user.message
 *   3. stream events:
 *        - assistant text / thinking → emit to subscribers (cockpit activity)
 *        - custom tool-use           → dispatch → send user.custom_tool_result
 *        - awaiting input / idle      → check done; if not & budget remains, nudge
 *   4. finish: mark study complete, surface report+model
 *
 * The loop is transport-agnostic about *how* events arrive: it consumes an async
 * iterable of events (real SDK stream, or a stubbed array in tests) and calls the
 * injected `agent` adapter to send messages/results back. This is what lets the
 * smoke test drive the whole thing with zero network.
 */

/**
 * @param {object} o
 * @param {string} o.studyId
 * @param {object} o.agent      adapter: { createSession, sendUserMessage, sendToolResult, streamEvents }
 * @param {object} o.dispatcher from makeDispatcher()
 * @param {object} o.controlPlane control-plane client (for the done check)
 * @param {(evt: object) => void} [o.emit] called for every event worth showing the human
 * @param {object} [o.opts]      { agentId, environmentId, maxToolCalls, outcomesEnabled, brief }
 */
export async function runStudyLoop({ studyId, agent, dispatcher, controlPlane, emit = () => {}, opts = {} }) {
  const {
    agentId,
    environmentId,
    maxToolCalls = 60,
    outcomesEnabled = false,
    brief, // { text } — the message that kicks off the work
  } = opts;

  const session = await agent.createSession({
    agentId,
    environmentId,
    title: `Labmate study ${studyId}`,
    metadata: { study_id: studyId },
  });
  const sessionId = session.id;
  emit({ kind: "session.created", study_id: studyId, session_id: sessionId });

  // Kick off the work.
  const kickoff =
    brief?.text ??
    `You are running Labmate study ${studyId}. Profile the dataset, review it for ` +
      `leakage, propose experiments (asking approval before compute), launch them in ` +
      `the Modal sandbox, critique each result, and iterate until the rubric is met. ` +
      `Start by calling profile_dataset for this study.`;
  await agent.sendUserMessage(sessionId, kickoff);
  emit({ kind: "user.message", study_id: studyId, text: kickoff });

  let toolCalls = 0;
  let done = false;

  for await (const event of agent.streamEvents(sessionId)) {
    const type = event.type ?? event.event ?? "";

    // 1. Surface assistant narration to the cockpit.
    if (type === "assistant.message" || type === "assistant.thinking" || type === "message") {
      emit({ kind: "agent.activity", study_id: studyId, event });
      continue;
    }

    // 2. Custom tool-use → execute for real → return the result.
    const toolUse = extractToolUse(event);
    if (toolUse) {
      toolCalls += 1;
      emit({ kind: "tool.use", study_id: studyId, name: toolUse.name, input: toolUse.input });

      if (toolCalls > maxToolCalls) {
        await agent.sendUserMessage(
          sessionId,
          "Tool-call budget reached. Write the report with what you have and stop.",
        );
        continue;
      }

      const result = await dispatcher.dispatch(toolUse.name, toolUse.input ?? {});
      emit({ kind: "tool.result", study_id: studyId, name: toolUse.name, result });
      await agent.sendToolResult(sessionId, toolUse.id, JSON.stringify(result), Boolean(result?.error));

      // After a report is written, check whether we're done.
      if (toolUse.name === "write_report") {
        done = await isDone({ studyId, controlPlane, outcomesEnabled, session: agent, sessionId });
        if (done) {
          emit({ kind: "study.done", study_id: studyId });
          break;
        }
      }
      continue;
    }

    // 3. The agent is waiting for us / went idle.
    if (type === "session.awaiting_input" || type === "session.idle" || type === "awaiting_input") {
      done = await isDone({ studyId, controlPlane, outcomesEnabled, session: agent, sessionId });
      if (done) {
        emit({ kind: "study.done", study_id: studyId });
        break;
      }
      await agent.sendUserMessage(
        sessionId,
        "Review the latest runs with query_runs. If an experiment beat the baseline " +
          "and survives a leakage/calibration check, promote it and write_report. " +
          "Otherwise propose the next experiment (request approval first) or stop.",
      );
      emit({ kind: "nudge", study_id: studyId });
      continue;
    }

    // 4. Terminal session states.
    if (type === "session.completed" || type === "session.failed" || type === "completed") {
      emit({ kind: "session.ended", study_id: studyId, event });
      break;
    }
  }

  return { sessionId, done, toolCalls };
}

/** Pull a custom tool-use out of an event, tolerating a few shapes across SDK versions. */
export function extractToolUse(event) {
  // Direct event form.
  if (event?.type === "assistant.custom_tool_use" || event?.type === "custom_tool_use") {
    return { id: event.custom_tool_use_id ?? event.id, name: event.name, input: event.input };
  }
  // Content-block form on an assistant message.
  const blocks = event?.message?.content ?? event?.content;
  if (Array.isArray(blocks)) {
    const tu = blocks.find((b) => b?.type === "custom_tool_use" || b?.type === "tool_use");
    if (tu) return { id: tu.id ?? tu.custom_tool_use_id, name: tu.name, input: tu.input };
  }
  return null;
}

/**
 * Done check. Prefer the Outcomes preview verdict when enabled; otherwise grade
 * against docs/rubric.json via the control plane (no preview access required).
 */
export async function isDone({ studyId, controlPlane, outcomesEnabled, session, sessionId }) {
  if (outcomesEnabled && session?.getOutcome) {
    try {
      const outcome = await session.getOutcome(sessionId);
      if (outcome?.status === "satisfied" || outcome?.verdict === "done") return true;
    } catch {
      /* fall through to rubric grade */
    }
  }
  const grade = await controlPlane.post("/api/grade", { study_id: studyId });
  return grade?.verdict === "done";
}

